DELETE FROM instrument_index_sources;
DELETE FROM instrument_risk_brackets;
DELETE FROM instrument_product_current_versions;
DELETE FROM instrument_current_versions WHERE symbol NOT IN (SELECT symbol FROM surprising_okx_instruments);
DELETE FROM instrument_symbol_sequences WHERE symbol NOT IN (SELECT symbol FROM surprising_okx_instruments);
DELETE FROM instruments WHERE symbol NOT IN (SELECT symbol FROM surprising_okx_instruments);

INSERT INTO instruments (
    symbol, version, instrument_type, contract_type, base_asset, quote_asset, settle_asset, contract_multiplier_ppm, contract_value_asset,
    price_tick_units, quantity_step_units, min_quantity_steps, max_quantity_steps, min_notional_units, max_notional_units, notional_multiplier_units,
    price_precision, quantity_precision, supported_order_types, supported_time_in_force, post_only_enabled, reduce_only_enabled, market_order_enabled,
    max_leverage_ppm, initial_margin_rate_ppm, maintenance_margin_rate_ppm, maker_fee_rate_ppm, taker_fee_rate_ppm, max_position_notional_units,
    user_open_interest_limit_rate_ppm, user_open_interest_limit_floor_units, funding_interval_hours, interest_rate_ppm, funding_rate_cap_ppm, funding_rate_floor_ppm,
    impact_notional_units, min_valid_index_sources, expiry_time, delivery_time, underlying_symbol, strike_price_units, option_type, option_exercise_style, settlement_method,
    status, effective_time, created_at, updated_at
)
SELECT symbol, 1, instrument_type, contract_type, base_asset, quote_asset, settle_asset, contract_multiplier_ppm, contract_value_asset, price_tick_units, quantity_step_units,
       min_quantity_steps, max_quantity_steps, 1, 1000000000000000000, notional_multiplier_units, price_precision, quantity_precision,
       CASE WHEN instrument_type IN ('SPOT', 'PERPETUAL') THEN 'LIMIT,MARKET' ELSE 'LIMIT' END, 'GTC,IOC,FOK,GTX', TRUE, instrument_type <> 'SPOT',
       instrument_type IN ('SPOT', 'PERPETUAL'), max_leverage_ppm, initial_margin_rate_ppm, maintenance_margin_rate_ppm,
       CASE WHEN instrument_type = 'SPOT' THEN 800 WHEN instrument_type = 'OPTION' THEN 200 ELSE 200 END,
       CASE WHEN instrument_type = 'SPOT' THEN 1000 WHEN instrument_type = 'OPTION' THEN 300 ELSE 500 END,
       1000000000000000000, 1000000, 25000000000000, funding_interval_hours, CASE WHEN instrument_type = 'PERPETUAL' THEN 100 ELSE 0 END,
       CASE WHEN instrument_type = 'PERPETUAL' THEN 3000 ELSE 0 END, CASE WHEN instrument_type = 'PERPETUAL' THEN -3000 ELSE 0 END,
       1000000000000, 1, CASE WHEN expiry_ms IS NULL THEN NULL ELSE to_timestamp(expiry_ms / 1000.0) END,
       CASE WHEN expiry_ms IS NULL THEN NULL ELSE to_timestamp(expiry_ms / 1000.0) END, underlying_symbol, strike_price_units, option_type,
       CASE WHEN instrument_type = 'OPTION' THEN 'EUROPEAN' END, CASE WHEN instrument_type IN ('DELIVERY', 'OPTION') THEN 'CASH' END,
       'TRADING', CASE WHEN effective_ms IS NULL THEN now() ELSE to_timestamp(effective_ms / 1000.0) END, now(), now()
  FROM surprising_okx_instruments
ON CONFLICT (symbol, version) DO UPDATE SET
    instrument_type=EXCLUDED.instrument_type, contract_type=EXCLUDED.contract_type, base_asset=EXCLUDED.base_asset, quote_asset=EXCLUDED.quote_asset, settle_asset=EXCLUDED.settle_asset,
    contract_multiplier_ppm=EXCLUDED.contract_multiplier_ppm, contract_value_asset=EXCLUDED.contract_value_asset, price_tick_units=EXCLUDED.price_tick_units, quantity_step_units=EXCLUDED.quantity_step_units,
    min_quantity_steps=EXCLUDED.min_quantity_steps, max_quantity_steps=EXCLUDED.max_quantity_steps, min_notional_units=EXCLUDED.min_notional_units, max_notional_units=EXCLUDED.max_notional_units, notional_multiplier_units=EXCLUDED.notional_multiplier_units,
    price_precision=EXCLUDED.price_precision, quantity_precision=EXCLUDED.quantity_precision, supported_order_types=EXCLUDED.supported_order_types, supported_time_in_force=EXCLUDED.supported_time_in_force,
    post_only_enabled=EXCLUDED.post_only_enabled, reduce_only_enabled=EXCLUDED.reduce_only_enabled, market_order_enabled=EXCLUDED.market_order_enabled, max_leverage_ppm=EXCLUDED.max_leverage_ppm, initial_margin_rate_ppm=EXCLUDED.initial_margin_rate_ppm, maintenance_margin_rate_ppm=EXCLUDED.maintenance_margin_rate_ppm,
    maker_fee_rate_ppm=EXCLUDED.maker_fee_rate_ppm, taker_fee_rate_ppm=EXCLUDED.taker_fee_rate_ppm, max_position_notional_units=EXCLUDED.max_position_notional_units, user_open_interest_limit_rate_ppm=EXCLUDED.user_open_interest_limit_rate_ppm, user_open_interest_limit_floor_units=EXCLUDED.user_open_interest_limit_floor_units,
    funding_interval_hours=EXCLUDED.funding_interval_hours, interest_rate_ppm=EXCLUDED.interest_rate_ppm, funding_rate_cap_ppm=EXCLUDED.funding_rate_cap_ppm, funding_rate_floor_ppm=EXCLUDED.funding_rate_floor_ppm, impact_notional_units=EXCLUDED.impact_notional_units, min_valid_index_sources=EXCLUDED.min_valid_index_sources,
    expiry_time=EXCLUDED.expiry_time, delivery_time=EXCLUDED.delivery_time, underlying_symbol=EXCLUDED.underlying_symbol, strike_price_units=EXCLUDED.strike_price_units, option_type=EXCLUDED.option_type, option_exercise_style=EXCLUDED.option_exercise_style, settlement_method=EXCLUDED.settlement_method, status=EXCLUDED.status, effective_time=EXCLUDED.effective_time, updated_at=now();

INSERT INTO instrument_current_versions (symbol, version, updated_at) SELECT symbol, 1, now() FROM surprising_okx_instruments
ON CONFLICT (symbol) DO UPDATE SET version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
INSERT INTO instrument_product_current_versions (product_line, symbol, version, updated_at) SELECT product_line, symbol, 1, now() FROM surprising_okx_instruments
ON CONFLICT (product_line, symbol) DO UPDATE SET version=EXCLUDED.version, updated_at=EXCLUDED.updated_at;
INSERT INTO instrument_symbol_sequences (symbol, version, updated_at) SELECT symbol, 1, now() FROM surprising_okx_instruments
ON CONFLICT (symbol) DO UPDATE SET version=GREATEST(instrument_symbol_sequences.version, EXCLUDED.version), updated_at=EXCLUDED.updated_at;

INSERT INTO instrument_risk_brackets (symbol, version, bracket_no, notional_floor_units, notional_cap_units, max_leverage_ppm, initial_margin_rate_ppm, maintenance_margin_rate_ppm)
SELECT symbol, 1, b.bracket_no, b.floor_units, b.cap_units, GREATEST(1000000::BIGINT, max_leverage_ppm / b.divisor),
       GREATEST(1::BIGINT, LEAST(5000::BIGINT, CEIL(1000000000000.0 / GREATEST(1000000::BIGINT, max_leverage_ppm / b.divisor)))),
       GREATEST(1::BIGINT, LEAST(5000::BIGINT, CEIL(1000000000000.0 / GREATEST(1000000::BIGINT, max_leverage_ppm / b.divisor)) / 2))
  FROM surprising_okx_instruments CROSS JOIN (VALUES (1,0::BIGINT,100000000000000::BIGINT,1::BIGINT),(2,100000000000000::BIGINT,500000000000000::BIGINT,2::BIGINT),(3,500000000000000::BIGINT,1000000000000000000,5::BIGINT)) b(bracket_no,floor_units,cap_units,divisor)
ON CONFLICT (symbol, version, bracket_no) DO UPDATE SET notional_floor_units=EXCLUDED.notional_floor_units, notional_cap_units=EXCLUDED.notional_cap_units, max_leverage_ppm=EXCLUDED.max_leverage_ppm, initial_margin_rate_ppm=EXCLUDED.initial_margin_rate_ppm, maintenance_margin_rate_ppm=EXCLUDED.maintenance_margin_rate_ppm;

INSERT INTO instrument_index_sources (symbol, version, source, enabled, base_url, path, source_symbol, parser, quote_currency, target_quote_currency, conversion_base_url, conversion_path, conversion_parser, conversion_mode, conversion_operation, fallback_weight_multiplier_ppm, websocket_enabled, websocket_url, websocket_subscribe_message, websocket_parser, weight_ppm)
SELECT symbol, 1, 'OKX', TRUE, 'https://www.okx.com', CASE WHEN spot_index THEN '/api/v5/market/ticker?instId='||index_symbol ELSE '/api/v5/market/index-ticker?instId='||index_symbol END, index_symbol, 'OKX_TICKER', quote_asset, quote_asset, NULL, NULL, NULL, 'DISCOUNT', 'MULTIPLY', 500000, TRUE, 'wss://ws.okx.com:8443/ws/v5/public', CASE WHEN spot_index THEN '{"op":"subscribe","args":[{"channel":"tickers","instId":"'||index_symbol||'"}]}' ELSE '{"op":"subscribe","args":[{"channel":"index-tickers","instId":"'||index_symbol||'"}]}' END, 'OKX_TICKER', 1000000
  FROM surprising_okx_instruments
ON CONFLICT (symbol, version, source) DO UPDATE SET enabled=EXCLUDED.enabled, base_url=EXCLUDED.base_url, path=EXCLUDED.path, source_symbol=EXCLUDED.source_symbol, parser=EXCLUDED.parser, quote_currency=EXCLUDED.quote_currency, target_quote_currency=EXCLUDED.target_quote_currency, websocket_subscribe_message=EXCLUDED.websocket_subscribe_message, websocket_parser=EXCLUDED.websocket_parser;

